/**
 * Runs synchronously by default for the demo dataset. For F500-scale
runs, pass `async=true` to enqueue the cycle on the background job
queue and poll `/jobs/{id}` for progress and result.

 * @summary Trigger the next OODA cycle
 */
export const getRunNextCycleUrl = (params?: RunNextCycleParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/cycles/run?${stringifiedParams}`
    : `/api/cycles/run`;
};

export const runNextCycle = async (
  params?: RunNextCycleParams,
  options?: RequestInit,
): Promise<RunCycleResponse | JobAccepted> => {
  return customFetch<RunCycleResponse | JobAccepted>(
    getRunNextCycleUrl(params),
    {
      ...options,
      method: "POST",
    },
  );
};

